from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log


def test_parse_transcript_log_flags_and_field_whitespace():
    assert parse_transcript_log([" a , 2 , 1 \n", "b, -3, 0", " c,4, \t"]) == [
        {"id": "a", "day": 2, "flagged": True},
        {"id": "b", "day": -3, "flagged": False},
        {"id": "c", "day": 4, "flagged": None},
    ]


def test_parse_transcript_log_skips_blank_and_comment_lines():
    lines = ["", "\n", " \t\n", "# comment", " \t# ignored,not,a,record", "x,1,0"]
    assert parse_transcript_log(iter(lines)) == [{"id": "x", "day": 1, "flagged": False}]
    assert parse_transcript_log(lines[:-1]) == []
    assert parse_transcript_log([]) == []


@pytest.mark.parametrize("bad_line", ["x,1", "x,1,0,extra", "x,no,1", "x,1.5,0", "x,,1"])
def test_parse_transcript_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_transcript_log(["", " # comment", " \t", "valid,2,1", bad_line])
    with pytest.raises(ValueError, match=r"\bline 1\b"):
        parse_transcript_log([bad_line])


def test_dedupe_transcripts_last_duplicate_id_wins_then_sorts():
    earlier = {"id": "a", "day": 9, "flagged": True}
    latest = {"id": "a", "day": 2, "flagged": None}
    b = {"id": "b", "day": 2, "flagged": True}
    c = {"id": "c", "day": 1, "flagged": False}
    events = [earlier, b, c, {"id": "a", "day": 0, "flagged": False}, latest]
    assert dedupe_transcripts(events) == [c, latest, b]
    assert events[0] == earlier
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_inclusive_zero_filled_and_range_limited():
    events = [
        {"day": 0, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 2, "flagged": False},
        {"day": 2, "flagged": None},
        {"day": 4, "flagged": True},
        {"day": 5, "flagged": True},
    ]
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 1, 1) == [2]
    assert daily_flag_counts(events, 4, 1) == []


def test_daily_flag_counts_empty_events():
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]
    assert daily_flag_counts([], 0, 0) == [0]
    assert daily_flag_counts([], 1, 0) == []
