from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_summary_pools_rounds_and_counts_nonempty_groups():
    groups = {
        "a": [{"id": "a", "day": 1, "flagged": True}],
        "b": [
            {"id": "b", "day": 4, "flagged": None},
            {"id": "c", "day": 4, "flagged": False},
        ],
        "empty": [],
    }
    assert monitor_summary(groups, 1) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 3)["recent"] == 0
    assert monitor_summary(groups, 4)["recent"] == 1
    assert monitor_summary(groups, 10)["recent"] == 1
    assert monitor_summary(groups, 0)["recent"] == 0


def test_monitor_summary_recent_counts_flags_across_groups():
    groups = {
        "a": [{"id": "a", "day": 3, "flagged": True}],
        "b": [
            {"id": "b", "day": 1, "flagged": True},
            {"id": "c", "day": 3, "flagged": True},
        ],
    }
    assert monitor_summary(groups, 2) == {"rate": 1.0, "recent": 2, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"a": []}])
def test_monitor_summary_empty(groups):
    assert monitor_summary(groups, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"flagged": True}, {"flagged": None}],
        "empty": [],
        "b": [{"flagged": True}, {"flagged": False}],
        "a": [{"flagged": False}],
        "c": [{"flagged": True}],
    }
    assert top_flagged_groups(groups, 3) == ["c", "b", "z"]
    assert top_flagged_groups(groups, 10) == ["c", "b", "z", "a"]
    assert top_flagged_groups(groups, 0) == []
    assert top_flagged_groups({}, 2) == []
    assert top_flagged_groups({"empty": []}, 2) == []
